(6519980, 969547, 117534, '<td valign="top">This style reminds me of Bear_Music, Magical!</td>', 'This style reminds me of Bear_Music, Magical!', '2011-08-29 20:25:07.000000', NULL, 1),
(6519982, 968773, 117534, '<td valign="top">All I can say is HOLY WOW! The shot of the house and the hillside without the city would even stand alone as a HOLY WOW</td>', 'All I can say is HOLY WOW! The shot of the house and the hillside without the city would even stand alone as a HOLY WOW', '2011-08-29 20:26:54.000000', NULL, 1),
(6519983, 969547, 39057, '<td valign="top">Good chance to win</td>', 'Good chance to win', '2011-08-29 20:29:53.000000', NULL, 1),
(6520006, 969783, 109227, '<td valign="top">My favorite; hope it does well for you.</td>', 'My favorite; hope it does well for you.', '2011-08-29 20:53:34.000000', NULL, 1),
(6520008, 969735, 109227, '<td valign="top">Nicely done; love the reflection.</td>', 'Nicely done; love the reflection.', '2011-08-29 20:54:23.000000', NULL, 1),
(6520009, 969768, 109227, '<td valign="top">Beautiful; love the tones and colors.</td>', 'Beautiful; love the tones and colors.', '2011-08-29 20:54:47.000000', NULL, 1),
(6520011, 969547, 109227, '<td valign="top">Beautiful.  Colors, clarity and light are great.</td>', 'Beautiful.  Colors, clarity and light are great.', '2011-08-29 20:55:47.000000', NULL, 1),
(6520013, 968773, 109227, '<td valign="top">Not sure if it''s me or the image, but the horizon does not look level. Nice perspective.</td>', 'Not sure if it''s me or the image, but the horizon does not look level. Nice perspective.', '2011-08-29 20:57:54.000000', NULL, 1),
(6520032, 969764, 98771, '<td valign="top">Nice image, would love to see it in color..</td>', 'Nice image, would love to see it in color..', '2011-08-29 21:24:26.000000', NULL, 1),
(6520039, 969701, 117912, '<td valign="top">The golden glow of sodium lights -  perhaps a little too enhanced in post with all the noise on the right and left of the frame</td>', 'The golden glow of sodium lights -  perhaps a little too enhanced in post with all the noise on the right and left of the frame', '2011-08-29 21:32:43.000000', NULL, 1),
(6520043, 969489, 117912, '<td valign="top">Reflections of trees lit from beneath - not a typical nightscape, but beautiful nonetheless.</td>', 'Reflections of trees lit from beneath - not a typical nightscape, but beautiful nonetheless.', '2011-08-29 21:33:37.000000', NULL, 1),
(6520044, 969430, 117912, '<td valign="top">Black and white adds to the feel of loneliness - looking out over the boats at the pier, the rain running off of the roof.</td>', 'Black and white adds to the feel of loneliness - looking out over the boats at the pier, the rain running off of the roof.', '2011-08-29 21:34:42.000000', NULL, 1),
(6520045, 969547, 117912, '<td valign="top">When water is as smooth as glass, it adds a surreal reflection - I often wonder what the sight is from below.</td>', 'When water is as smooth as glass, it adds a surreal reflection - I often wonder what the sight is from below.', '2011-08-29 21:35:47.000000', NULL, 1),
(6520046, 969605, 121692, '<td valign="top">Very cool shot :)</td>', 'Very cool shot :)', '2011-08-29 21:36:00.000000', NULL, 1),
(6520047, 969543, 117912, '<td valign="top">Great eye for a beautiful capture - I hear hawks daily while at work but seldom see them up close.</td>', 'Great eye for a beautiful capture - I hear hawks daily while at work but seldom see them up close.', '2011-08-29 21:36:33.000000', NULL, 1),
(6520051, 969780, 117912, '<td valign="top">An interesting vantage point makes for a stunning picture - though I''m sure a skilled hand at post made a lot of difference as well.</td>', 'An interesting vantage point makes for a stunning picture - though I''m sure a skilled hand at post made a lot of difference as well.', '2011-08-29 21:38:25.000000', NULL, 1),
(6520052, 969738, 117912, '<td valign="top">Sunsets and silhouettes are always beautiful - I love the way the cloud in the back mimics the trees in the foreground.</td>', 'Sunsets and silhouettes are always beautiful - I love the way the cloud in the back mimics the trees in the foreground.', '2011-08-29 21:39:20.000000', NULL, 1),
(6520054, 968865, 117912, '<td valign="top">Isn''t it amazing when reflections show more than the original - nice capture, but is feels a little dark.</td>', 'Isn''t it amazing when reflections show more than the original - nice capture, but is feels a little dark.', '2011-08-29 21:40:44.000000', NULL, 1),
(6520056, 969709, 117912, '<td valign="top">Almost pointillism - like it was printed on sandpaper.</td>', 'Almost pointillism - like it was printed on sandpaper.', '2011-08-29 21:41:51.000000', NULL, 1),
(6520057, 969717, 117912, '<td valign="top">Excellent DOF, but the foreground seems a little cluttered with the weeds and algae.</td>', 'Excellent DOF, but the foreground seems a little cluttered with the weeds and algae.', '2011-08-29 21:42:46.000000', NULL, 1),
(6520060, 969336, 117912, '<td valign="top">Interesting play of filters and layers - it makes it appear clearly 3 dimensional on the screen - which makes it feel artificial unfortunately.</td>', 'Interesting play of filters and layers - it makes it appear clearly 3 dimensional on the screen - which makes it feel artificial unfortunately.', '2011-08-29 21:44:33.000000', NULL, 1),
(6520061, 969764, 117912, '<td valign="top">Mother nature has a cameo - An interesting show I''m sure - though I feel the black and white processing may have let this scene down.</td>', 'Mother nature has a cameo - An interesting show I''m sure - though I feel the black and white processing may have let this scene down.', '2011-08-29 21:45:54.000000', NULL, 1),
(6520062, 969778, 117912, '<td valign="top">Novel choice in processing with both a black and white and inverse conversion - it appears to be light painting - or in this case dark painting.  Original and surreal.</td>', 'Novel choice in processing with both a black and white and inverse conversion - it appears to be light painting - or in this case dark painting.  Original and surreal.', '2011-08-29 21:47:34.000000', NULL, 1),
(6520064, 969694, 117912, '<td valign="top">Nice low point of view looking up the path - taken closer to the "gold hour" this would be a knockout.</td>', 'Nice low point of view looking up the path - taken closer to the "gold hour" this would be a knockout.', '2011-08-29 21:48:43.000000', NULL, 1),
(6520067, 969558, 117912, '<td valign="top">It''s sad that there is so much light pollution - often unknowingly.  Interesting composition - the vehicle streaking through adds to the overall feel.</td>', 'It''s sad that there is so much light pollution - often unknowingly.  Interesting composition - the vehicle streaking through adds to the overall feel.', '2011-08-29 21:50:02.000000', NULL, 1),
(6520069, 969586, 117912, '<td valign="top">It''s a beautiful tree, but as the subject of a nightscape, it''s a little too up front - maybe if it was more over to the side and framing the background it would seem less obtrusive - the tonemapping didn''t add to the overall picture in my opinion.</td>', 'It''s a beautiful tree, but as the subject of a nightscape, it''s a little too up front - maybe if it was more over to the side and framing the background it would seem less obtrusive - the tonemapping didn''t add to the overall picture in my opinion.', '2011-08-29 21:51:58.000000', NULL, 1),
(6520072, 969785, 117912, '<td valign="top">Even a motel can be a home, though I doubt that I would want to remember it in this fashion.</td>', 'Even a motel can be a home, though I doubt that I would want to remember it in this fashion.', '2011-08-29 21:52:47.000000', NULL, 1),
(6520076, 969782, 117912, '<td valign="top">An interesting layout, but I don''t see a clear subject - just a couple of paths that don''t tell me anything.</td>', 'An interesting layout, but I don''t see a clear subject - just a couple of paths that don''t tell me anything.', '2011-08-29 21:53:45.000000', NULL, 1),
(6520078, 969725, 123833, '<td valign="top">Nice and my top for the challenge. It does capture the meaning of "rural". Nice toning.</td>', 'Nice and my top for the challenge. It does capture the meaning of "rural". Nice toning.', '2011-08-29 21:54:20.000000', NULL, 1),
(6520079, 969336, 123833, '<td valign="top">Great toning</td>', 'Great toning', '2011-08-29 21:54:27.000000', NULL, 1),
(6520080, 969735, 123833, '<td valign="top">Nice image but there are no lights anywhere to indicate it is night time. But the movement of clouds indicates long exposure.</td>', 'Nice image but there are no lights anywhere to indicate it is night time. But the movement of clouds indicates long exposure.', '2011-08-29 21:54:42.000000', NULL, 1),
(6520081, 969701, 123833, '<td valign="top">Lots of lights in your small town!</td>', 'Lots of lights in your small town!', '2011-08-29 21:54:49.000000', NULL, 1),
(6520082, 969541, 117912, '<td valign="top">An interesting low perspective and a nod to light and shadow - there''s a story here, but it escapes me.</td>', 'An interesting low perspective and a nod to light and shadow - there''s a story here, but it escapes me.', '2011-08-29 21:54:58.000000', NULL, 1),
